import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"37、【家人】 离下巽上","description":"温公易说 - 37、【家人】 离下巽上","frontmatter":{"title":"37、【家人】 离下巽上","description":"温公易说 - 37、【家人】 离下巽上"},"headers":[],"relativePath":"zh/classics/wengong/038.md","filePath":"zh/classics/wengong/038.md"}'),n={name:"zh/classics/wengong/038.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_37、【家人】-离下巽上" tabindex="-1">37、【家人】 离下巽上 <a class="header-anchor" href="#_37、【家人】-离下巽上" aria-label="Permalink to “37、【家人】 离下巽上”">​</a></h1><h3 id="彖曰-家人-女正位乎内-男正位乎外-男女正-天地之大义也。家人有严君焉-父母之谓也。父父子子-兄兄弟弟-夫夫妇妇-而家道正。正家而天下定矣。" tabindex="-1">彖曰：家人，女正位乎内，男正位乎外，男女正，天地之大义也。家人有严君焉，父母之谓也。父父子子，兄兄弟弟，夫夫妇妇，而家道正。正家而天下定矣。 <a class="header-anchor" href="#彖曰-家人-女正位乎内-男正位乎外-男女正-天地之大义也。家人有严君焉-父母之谓也。父父子子-兄兄弟弟-夫夫妇妇-而家道正。正家而天下定矣。" aria-label="Permalink to “彖曰：家人，女正位乎内，男正位乎外，男女正，天地之大义也。家人有严君焉，父母之谓也。父父子子，兄兄弟弟，夫夫妇妇，而家道正。正家而天下定矣。”">​</a></h3><p>家者，治之至小者也，然有严君之道焉，严恭也。知事亲则知事君矣。</p><h3 id="象曰-风自火出-家人。君子以言有物而行有恒。" tabindex="-1">象曰：风自火出，家人。君子以言有物而行有恒。 <a class="header-anchor" href="#象曰-风自火出-家人。君子以言有物而行有恒。" aria-label="Permalink to “象曰：风自火出，家人。君子以言有物而行有恒。”">​</a></h3><h3 id="初九-闲有家-悔亡-象曰-闲有家-志未变也。" tabindex="-1">初九：闲有家，悔亡 象曰：闲有家，志未变也。 <a class="header-anchor" href="#初九-闲有家-悔亡-象曰-闲有家-志未变也。" aria-label="Permalink to “初九：闲有家，悔亡 象曰：闲有家，志未变也。”">​</a></h3><h3 id="六二-无攸遂-在中馈-贞吉-象曰-六二之吉-顺以巽也。" tabindex="-1">六二：无攸遂，在中馈，贞吉 象曰：六二之吉，顺以巽也。 <a class="header-anchor" href="#六二-无攸遂-在中馈-贞吉-象曰-六二之吉-顺以巽也。" aria-label="Permalink to “六二：无攸遂，在中馈，贞吉 象曰：六二之吉，顺以巽也。”">​</a></h3><h3 id="九三-家人嗃嗃-悔厉-吉-妇子嘻嘻-终吝-象曰-家人嗃嗃-未失也-妇子嘻嘻-失家节也。" tabindex="-1">九三：家人嗃嗃，悔厉，吉；妇子嘻嘻，终吝 象曰：家人嗃嗃，未失也；妇子嘻嘻，失家节也。 <a class="header-anchor" href="#九三-家人嗃嗃-悔厉-吉-妇子嘻嘻-终吝-象曰-家人嗃嗃-未失也-妇子嘻嘻-失家节也。" aria-label="Permalink to “九三：家人嗃嗃，悔厉，吉；妇子嘻嘻，终吝 象曰：家人嗃嗃，未失也；妇子嘻嘻，失家节也。”">​</a></h3><h3 id="六四-富家-大吉-象曰-富家大吉-顺在位也。" tabindex="-1">六四：富家，大吉 象曰：富家大吉，顺在位也。 <a class="header-anchor" href="#六四-富家-大吉-象曰-富家大吉-顺在位也。" aria-label="Permalink to “六四：富家，大吉 象曰：富家大吉，顺在位也。”">​</a></h3><h3 id="九五-王假有家-勿恤-吉-象曰-王假有家-交相爱也。" tabindex="-1">九五：王假有家，勿恤，吉 象曰：王假有家，交相爱也。 <a class="header-anchor" href="#九五-王假有家-勿恤-吉-象曰-王假有家-交相爱也。" aria-label="Permalink to “九五：王假有家，勿恤，吉 象曰：王假有家，交相爱也。”">​</a></h3><p>假大也。文王刑于寡妻，至于兄弟，以御于家邦。大其家以至于有天下，亲其亲以及人之亲，长其长以及人之长。上下交相爱，而天下和矣。故曰交相爱也。</p><h3 id="上九-有孚-威如-终吉-象曰-威如之吉-反身之谓也。" tabindex="-1">上九：有孚，威如，终吉 象曰：威如之吉，反身之谓也。 <a class="header-anchor" href="#上九-有孚-威如-终吉-象曰-威如之吉-反身之谓也。" aria-label="Permalink to “上九：有孚，威如，终吉 象曰：威如之吉，反身之谓也。”">​</a></h3><p>上九以阳居上，家之至尊者也。家人望之以为表式，苟其身不正，则虽令不从。是以内尽至诚，为人所信，然后有威可畏，而获终吉也。大学曰：欲齐其家者，先修其身；欲修其身者，先正其心；欲正其心者，先诚其意。此之谓也。</p>',12)])])}const m=e(n,[["render",l]]);export{b as __pageData,m as default};
